head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.colorCnt = 0; // 조회한 이후에만 컬럼에  color 변경하기 위한 변수
scwin.excel_name = "";
// 화면 리사이징

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gUpDepCd;
scwin.gIsurCd;

scwin.BsColumnID = new Array('totalassets', 'totalliabilities', 'totalstockholdersequity', 'currentassets', 'noncurrentassets', 'currentliabilities', 'noncurrentliabilities', 'capitalstock', 'capitalsurplus', 'accumulatedothercomprehensiveincome', 'dominationcorp', 'nondominationshard');
scwin.IsColumnID = new Array('salesrevenue', 'costgoodsservicessold', 'grossprofitloss', 'operatingincomeloss', 'incometaxesexpenses', 'ongoingbusinessincomelossbeforeincometaxesexpenses', 'financerevenue', 'totalcomprehensive', 'netincomelossincomestatement', 'plattrownersofpar', 'plattrnonconinter');
scwin.BasicColumnID = new Array('LIST_STAT_NM', 'IDX_IND_UPCLSS_NM', 'MID_IDX_IND_NM', 'DISCLS_PROCS_DDTM', 'ORGN_DISCLS_DDTM', 'DEP_NM', 'EMP_NM', 'FORM_KOR_NM', 'STD_IND_NM', 'ENTPR_GRP_NM', 'COM_ATTR_TP_NM', 'ACNTCLS_YY', 'ACNTCLS_MM');
scwin.KosColumnID = new Array('SECT_TP_NM', 'KOSDAQ_MID_300', 'KOSDAQ_SMALL', 'KOSTAR', 'PREMIER_YN', 'KOSDAQ_100', 'KOSDAQ_50');

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
        scwin.init();
        $c.cm.fn_com_isur(txb_isur_cd, txb_COM_NM);
        scwin.allDisCheck();
        scwin.showGridField('HIDDEN');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26302.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear(), 10);
    let str = "";
    for (let i = yyyy; i >= 2010; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    // alert(str);
    cmb_FISCYY.CBData = str;
    rdo_MKT_ID.setValue(js_market);
    if (js_market === "9") {
        rdo_MKT_ID.setDisabled(false);
        rdo_MKT_ID.setValue("1");
    } else {
        // 콘트롤 잠그기.
        $c.cm.setColumnProp(grd_Grid, "MKT_NM", "Show", false);
        rdo_MKT_ID.setDisabled(true);
    }
    grd_Grid.EnableTabKey(false);
    if (scwin.gLdMktTp !== '2') {
        panel_5.hide();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF26302.xml', SCREN_PROCS_TP_CD_07);
        // grd_Grid.GridToExcel('재무속보','' , 8);
        $c.data.downloadGridViewOffice(grd_Grid, "IFRS재무속보기초데이타", "IFRS재무속보기초데이타.xlsx", "8", 0); // 엑셀 다운로드
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26302.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotalCnt.setValue("총건수 : " + rowcount);
        cnt = dts_Grid.getCellData(0, "COM_CNT");
        if (isNaN(cnt)) {
            cnt = "0";
        }
        txb_companyCnt.setValue("총회사수 : " + cnt);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26302.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26302.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26302.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26302.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26302.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26302.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26302.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26302.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name dts_emp_OnLoadCompleted
 * @description dts_emp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    // setObjectValue(cmb_EmpList, js_emp_no) ;

};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description emp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "" || scwin.gDepCd === "UPTEAM") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_emp.getCellData(row, "dep_cd") === "UPTEAM" ||
                dts_emp.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26302.dts_emp_OnFilter" });
    }
};

/**
 * @method
 * @name dts_dep_OnLoadCompleted
 * @description dts_dep 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    try {
        if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34') {
            $c.stf.copyDataSet(dts_dep, dts_dep1);
            scwin.addDsclTeamAll(rowcount);
            cmb_TeamList.setValue('UPTEAM');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26302.dts_dep_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        scwin.gIsurCd = dts_Grid.getCellData(row, "ISUR_CD2");
        // gIsurCd = gIsurCd.substring(0,5);
        const AcptNo = dts_Grid.getCellData(row, "KEY_ACPT_NO");
        if (colid === "PUBL_DDTM") {
            await $c.stf.openDisclViewer(AcptNo, "R");
        } else if (colid === "COM_NM") {
            $c.stf.fn_PopupCorpInfo();
        } else if (colid === "FS_ACNT_TP_NM") {
            scwin.excel_name = dts_Grid.getCellData(row, "COM_NM") + "분기보고서.xls";
            // fn_getUsrDisclViewerInfo(AcptNo);

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26302.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnUserColor
 * @description grd Grid On User Color 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnUserColor = function(row, colid) {
    try {
        let colorName = "#77FF88"; // 11FF00";
        const value = "";
        const column = new Array("ASSETS1", "ASSETS2", "LIABILITIES1", "LIABILITIES2", "EQUITY1", "EQUITY2", "CURRENTASSETS1", "CURRENTASSETS2", "NONCURRENTASSETS1", "NONCURRENTASSETS2", "CURRENTLIABILITIES1", "CURRENTLIABILITIES2", "NONCURRENTLIABILITIES1", "NONCURRENTLIABILITIES2", "ISSUEDCAPITAL1", "ISSUEDCAPITAL2", "PROPERTYPLANTEQUIPMENT1", "PROPERTYPLANTEQUIPMENT2", "CAPITALSURPLUS1", "CAPITALSURPLUS2", "ACCOTHCOMINCOME1", "ACCOTHCOMINCOME2", "OWNERSOFPARENT1", "OWNERSOFPARENT2", "NONOWNERSOFPARENT1", "NONOWNERSOFPARENT2", "REVENUE1", "REVENUE2", "REVENUE3", "REVENUE4", "COSTOFSALES1", "COSTOFSALES2", "COSTOFSALES3", "COSTOFSALES4", "GROSSPROFIT1", "GROSSPROFIT2", "GROSSPROFIT3", "GROSSPROFIT4", "OPERATINGINCOMELOSS1", "OPERATINGINCOMELOSS2", "OPERATINGINCOMELOSS3", "OPERATINGINCOMELOSS4", "INCOMETAXESEXPENSES1", "INCOMETAXESEXPENSES2", "INCOMETAXESEXPENSES3", "INCOMETAXESEXPENSES4", "PROFITLOSSBFTAX1", "PROFITLOSSBFTAX2", "PROFITLOSSBFTAX3", "PROFITLOSSBFTAX4", "FINANCEINCOME1", "FINANCEINCOME2", "FINANCEINCOME3", "FINANCEINCOME4", "COMPREHENSIVEINCOME1", "COMPREHENSIVEINCOME2", "COMPREHENSIVEINCOME3", "COMPREHENSIVEINCOME4", "PROFITLOSS1", "PROFITLOSS2", "PROFITLOSS3", "PROFITLOSS4");
        let cell = "";
        if (dts_Grid.getCellData(row, "ACPT_NO") === null || dts_Grid.getCellData(row, "ACPT_NO") === undefined) {
            return;
            colorName = "#ffffff"; // 데이타가 없으면 흰색으로

        }

        // 회사정보결산월과 xbrl 재무정보의 결산월 비교
        if (colid === "acolor100") {
            const mm1 = dts_Grid.getCellData(row, "ACNTCLS_MM");
            const mm2 = dts_Grid.getCellData(row, "ACNTCLS_MMDD1");
            if (scwin.colorCnt > 0 && mm1 !== mm2) {
                return colorName; // 연두색
            } else {
                return "#ffffff";
            }
        }
        if (colid === "acolor101") {
            check1 = dts_Grid.getCellData(row, "AUDT_OPIN_TP_NM");
            if (scwin.colorCnt > 0 && check1 !== "적정" && check1 !== "의견거절" && check1 !== "한정" && check1 !== "부적정") {
                return colorName; // 연두색
            } else {
                return "#ffffff";
            }
        }
        for (let i = 0; i < column.length; i++) {
            cell = "acolor" + (i + 1);
            if (colid === cell) {
                // 모든 필드 '0' or '' 인지 체크한다.
                value.setValue(dts_Grid.getCellData(row, column[i]));
                if (scwin.colorCnt > 0 && colid === 'acolor1') {
                    // 자산총계 = 부채총계 + 자본총계
                    value1 = parseInt(dts_Grid.getCellData(row, "ASSETS1"));
                    value2 = parseInt(dts_Grid.getCellData(row, "LIABILITIES1"));
                    value3 = parseInt(dts_Grid.getCellData(row, "EQUITY1"));
                    value4 = parseInt(dts_Grid.getCellData(row, "CURRENTASSETS1")); // 유동자산
                    value5 = parseInt(dts_Grid.getCellData(row, "NONCURRENTASSETS1")); // 비유동자산
                    if ((value1 !== value2 + value3) || (value1 !== value4 + value5)) {
                        return colorName;
                    } else {
                        return "#ffffff";
                    }
                } else if (scwin.colorCnt > 0 && colid === 'acolor2') {
                    // 자산총계 = 부채총계 + 자본총계
                    value1 = parseInt(dts_Grid.getCellData(row, "ASSETS2"));
                    value2 = parseInt(dts_Grid.getCellData(row, "LIABILITIES2"));
                    value3 = parseInt(dts_Grid.getCellData(row, "EQUITY2"));
                    value4 = parseInt(dts_Grid.getCellData(row, "CURRENTASSETS2")); // 유동자산
                    value5 = parseInt(dts_Grid.getCellData(row, "NONCURRENTASSETS2")); // 비유동자산
                    if ((value1 !== value2 + value3) || (value1 !== value4 + value5)) {
                        return colorName;
                    } else {
                        return "#ffffff";
                    }
                } else if (scwin.colorCnt > 0 && colid === 'acolor3') {
                    // 부채총계 = 유동부채 + 비유동부채
                    value1 = parseInt(dts_Grid.getCellData(row, "LIABILITIES1"));
                    value2 = parseInt(dts_Grid.getCellData(row, "CURRENTLIABILITIES1"));
                    value3 = parseInt(dts_Grid.getCellData(row, "NONCURRENTLIABILITIES1"));
                    if (value1 !== value2 + value3) {
                        return colorName;
                    } else {
                        return "#ffffff";
                    }
                } else if (scwin.colorCnt > 0 && colid === 'acolor4') {
                    // 부채총계 = 유동부채 + 비유동부채
                    value1 = parseInt(dts_Grid.getCellData(row, "LIABILITIES2"));
                    value2 = parseInt(dts_Grid.getCellData(row, "CURRENTLIABILITIES2"));
                    value3 = parseInt(dts_Grid.getCellData(row, "NONCURRENTLIABILITIES2"));
                    if (value1 !== value2 + value3) {
                        return colorName;
                    } else {
                        return "#ffffff";
                    }
                } else {
                    return "#ffffff";
                }
                // }

            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26302.grd_Grid_OnUserColor" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26302.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name cmb_TeamList_onselchange
 * @description cmb_TeamList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_onselchange = function() {
    try {
        scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
        if (scwin.gDepCd === '' || scwin.gDepCd === 'UPTEAM') {
            cmb_EmpList.setValue('');
        }
        dts_emp.UseFilter = true;
        dts_emp.Filter();
        dts_emp.sort("DEP_CD", 0);
        // dts_emp.sort(); // W-Craft 주석처리
        if (scwin.gDepCd !== '' && scwin.gDepCd !== 'UPTEAM') {
            cmb_EmpList.trigger("onclick");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26302.cmb_TeamList_onselchange" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26302.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26302.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26302.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26302.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name cmb_IndTp_onselchange
 * @description cmb_IndTp onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_IndTp_onselchange = async function() {
    try {
        const vValue = $c.cp.valueOfIndex(cmb_IndTp, "VALUE", cmb_IndTp.getSelectedIndex());
        if (vValue !== '') {
            // 전체일때 제외한 나머지경우
            await scwin.checkComNmCond();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26302.cmb_IndTp_onselchange" });
    }
};

