/**
 * @method
 * @name dts_viewer_OnLoadCompleted
 * @description dts_viewer 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_viewer_OnLoadCompleted = async function(rowcount) {
