/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    scwin.colorCnt = 1; // 조회를 클릭한 경우에만 컬럼 color 변경해줌

    let flag = rdo_MKT_ID.getValue();
    const vFISCYY = cmb_FISCYY.getValue();
    const vISUR_CD = txb_isur_cd.getValue();
    if (flag === "9" || flag === "") {
        await $c.win.alert("[시장구분]을 선택하세요.");
        rdo_MKT_ID.focus();
        return;
    } else {
        scwin.gDepCd = cmb_TeamList.getValue();
        scwin.gEmpNo = cmb_EmpList.getValue();
        if (scwin.gEmpNo === "") {
            scwin.gEmpNo = '%';
        }
        if (scwin.gDepCd === "") {
            scwin.gDepCd = 'all';
        }
        scwin.changeHeader();
        url += "&MKT_ID=" + rdo_MKT_ID.getValue();
        url += "&FISCYY=" + vFISCYY;
        url += "&MM=" + cmb_MM.getValue();
        url += "&RPT_KIND=" + cmb_RPT_KIND.getValue();
        url += "&ISUR_CD=" + vISUR_CD;
        url += "&DEP_CD=" + scwin.gDepCd;
        url += "&EMP_NO=" + scwin.gEmpNo;
        url += "&UP_DEP_CD=" + js_belngdepcd;
        url += "&IND_TP=" + cmb_IndTp.getValue();
        url += "&COM_GRP=" + cmb_com_grp.getValue();
        url += "&MON_UNIT=" + cmb_mon_unit.getValue();
        url += "&FS_ACNT_TP_CD=" + rdo_FS.getValue();
        url += "&SCREN_ID=" + 'ULDSTF26302.xml';
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_Grid",
            action : "/IfrsDisclosureStatistics.do",
            ref : "",
            target : "dts_Grid=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        let str = dts_Grid.getCellData(1, 5);

    }
};

