/**
 * @method
 * @name bsCheck
 * @description bs Check 처리
 * @param {*} mode mode
 * @returns {void}
 * @hidden N
 */
scwin.bsCheck = function(mode) {
    let checkYN = 'Y';
    let j = 0;
    let flag = 'SHOW';
    for (let i = 0; i < scwin.BsColumnID.length; i++) {
        if ($p.getComponentById('checkbox_' + scwin.BsColumnID[i]).checked) {
            j++;
        }
    }
    if (j === scwin.BsColumnID.length) {
        checkYN = 'N';
    }
    if ((checkYN === 'N' || mode === 'unCheck') && mode !== 'allCheck') {
        for (let i = 0; i < scwin.BsColumnID.length; i++) {
            $p.getComponentById('checkbox_' + scwin.BsColumnID[i]).setValue(0);
        }
        flag = 'HIDDEN';
    } else {
        for (let i = 0; i < scwin.BsColumnID.length; i++) {
            $p.getComponentById('checkbox_' + scwin.BsColumnID[i]).setValue(1);
        }
    }
    scwin.bsShowColumn(flag);
};

