        }
    }
};

/**
 * @method
 * @name kosShowColumn
 * @description kos Show Column 처리
 * @param {String} flag flag
 * @returns {void}
 * @hidden N
 */
scwin.kosShowColumn = function(flag) {
    if (flag === 'SHOW') {
        for (let i = 0; i < scwin.KosColumnID.length; i++) {
            $c.cm.setColumnProp(grd_Grid, scwin.KosColumnID[i], 'Show', true);
        }
    } else {
        for (let i = 0; i < scwin.KosColumnID.length; i++) {
            $c.cm.setColumnProp(grd_Grid, scwin.KosColumnID[i], 'Show', false);
        }
    }
};

/**
 * @method
 * @name showGridField
 * @description show Grid Field 처리
 * @param {String} flag flag
 * @returns {void}
 * @hidden N
 */
scwin.showGridField = function(flag) {
    scwin.bsShowColumn(flag);
    scwin.isShowColumn(flag);
    scwin.basicShowColumn(flag);
    scwin.kosShowColumn(flag);
};

/**
 * @method
 * @name validationCheckBox
 * @description 밑의 재무속보 검증식에서 검증식 클릭시 기존에 선택된 계정항목들 체크박스를(금액관련계정들만) 초기화한다.
 * @returns {void}
 * @hidden N
 */
scwin.validationCheckBox = function() {
    scwin.bsCheck('unCheck');
    scwin.isCheck('unCheck');
};

/**
 * @method
 * @name validationShowGridField
 * @description 밑의 재무속보 검증식에서 검증식 클릭시 기존에 선택된 계정항목들 체크박스를(금액관련계정들만) 초기화한다.
 * @returns {void}
 * @hidden N
 */
scwin.validationShowGridField = function() {
    scwin.bsShowColumn('HIDDEN');
    scwin.isShowColumn('HIDDEN');
};

/**
 * @method
 * @name checkBox
 * @description check Box 처리
 * @param {*} id id
 * @returns {void}
 * @hidden N
 */
scwin.checkBox = function(id) {
    if ($p.getComponentById('checkbox_' + id).checked) {
        $c.cm.setColumnProp(grd_Grid, id, 'Show', true);
    } else {
        $c.cm.setColumnProp(grd_Grid, id, 'Show', false);
    }
};

/**
 * @method
 * @name openUsrDisclViewer
 * @description open Usr Discl Viewer 처리
 * @param {String} flag flag
 * @param {*} acpt_no acpt_no
 * @param {*} discls_doc_no discls_doc_no
 * @param {*} work_directory work_directory
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openUsrDisclViewer = async function(flag, acpt_no, discls_doc_no, work_directory) {
    const bPath = work_directory;
    const html_body_url = "/" + ACPT_NO.substring(0, 4) + "/" + ACPT_NO.substring(4, 6) + "/" + ACPT_NO.substring(6, 8) + "/" + ACPT_NO.substring(8) + "/" + discls_doc_no + "/" + acpt_no + ".html";
    const excel_body_url = "/" + ACPT_NO.substring(0, 4) + "/" + ACPT_NO.substring(4, 6) + "/" + ACPT_NO.substring(6, 8) + "/" + ACPT_NO.substring(8) + "/" + discls_doc_no + "/" + acpt_no + ".xls";
    let url = "/dsclproc/JLDSTF10006.jsp?bPath=" + bPath + "&html_body_url=" + html_body_url + "&excel_body_url=" + excel_body_url + "&excel_name=" + scwin.excel_name + "&acpt_no=" + acpt_no;
    await $c.frame.CreateDialogFrame("viewer" + acpt_no, url, "사용자뷰어", 100, 10, 1000, 800, "window");
};
